INSERT INTO policies (policy_code, title, category, version, effective_date, department_id, summary, full_text, status) SELECT 'POL-01', 'Zero Data Leakage & Customer Privacy Policy', 'Data Privacy', 'v3.2', '2024-01-01', id, 'Guarantees customer dataset rows, prompts, and embeddings are NEVER used to train foundational AI models.', 'NexaData AI enforces strict tenant isolation. Customer documents and database rows are indexed into cryptographically isolated vector namespaces. All LLM inferences are executed under zero-retention agreements. Data is encrypted in transit (TLS 1.3) and at rest (AES-256). Ephemeral memory scrubbing occurs immediately upon query resolution.', 'Active' FROM departments WHERE department_code = 'DEP-SEC';
INSERT INTO policies (policy_code, title, category, version, effective_date, department_id, summary, full_text, status) SELECT 'POL-02', 'Service Level Agreement (SLA) & Uptime Guarantee', 'SLA & Uptime', 'v2.5', '2024-03-15', id, 'Establishes a 99.99% availability SLA for Platinum tiers and outlines pro-rated credit refunds for unplanned downtime.', 'NexaData guarantees 99.99% monthly uptime for Platinum Enterprise Engine deployments and 99.9% for Cloud Analytics tiers. Uptime is calculated excluding scheduled maintenance windows announced 72 hours in advance. If availability dips below the threshold, customers receive a 10% credit for every 0.1% downtime below SLA, up to 100% of the monthly fee.', 'Active' FROM departments WHERE department_code = 'DEP-ENG';
INSERT INTO policies (policy_code, title, category, version, effective_date, department_id, summary, full_text, status) SELECT 'POL-03', '14-Day Money-Back Satisfaction Guarantee & Billing Terms', 'Billing & Refunds', 'v2.0', '2023-09-01', id, 'Provides a 100% refund guarantee within 14 calendar days of initial deployment for all enterprise subscription plans.', 'All new NexaData AI software subscription plans include an unconditional 14-day 100% money-back satisfaction guarantee. If the platform does not meet enterprise technical requirements, written notice sent to support@nexadata.ai within 14 days will initiate a full refund. Annual contracts billed in advance are non-refundable after the 14-day evaluation window.', 'Active' FROM departments WHERE department_code = 'DEP-FIN';
INSERT INTO policies (policy_code, title, category, version, effective_date, department_id, summary, full_text, status) SELECT 'POL-04', 'SOC2 Type II & FedRAMP Information Security Standard', 'Security & Compliance', 'v4.0', '2024-02-01', id, 'Specifies audit controls, annual penetration testing, multi-factor authentication, and RBAC requirements.', 'NexaData complies with AICPA SOC2 Type II Trust Services Criteria (Security, Availability, Confidentiality) and FedRAMP High baseline requirements. Access to production environments requires hardware-backed FIPS 140-2 keys (YubiKey) and time-bound approval from two security officers. Annual third-party penetration tests are made available under NDA.', 'Active' FROM departments WHERE department_code = 'DEP-SEC';
INSERT INTO policies (policy_code, title, category, version, effective_date, department_id, summary, full_text, status) SELECT 'POL-05', 'Acceptable Use & Autonomous AI Safety Guidelines', 'Acceptable Use', 'v1.8', '2024-05-10', id, 'Restricts deployment of NexaData models for malicious surveillance, autonomous weapons, or deceptive practices.', 'NexaData AI technologies may not be employed for unlawful surveillance, automated discriminatory credit or hiring decisions without human review, generation of deceptive media, or weaponized autonomous systems. Violation results in immediate suspension of API keys and cancellation of contracts.', 'Active' FROM departments WHERE department_code = 'DEP-RES';
INSERT INTO policies (policy_code, title, category, version, effective_date, department_id, summary, full_text, status) SELECT 'POL-06', 'Disaster Recovery & Business Continuity Framework', 'Disaster Recovery', 'v2.2', '2024-06-01', id, 'Defines Recovery Point Objective (RPO < 1 min) and Recovery Time Objective (RTO < 5 min) across multi-cloud regions.', 'Production databases and vector indexes are continuously mirrored across independent availability zones (US-East and US-West). In the event of catastrophic regional cloud failure, automated DNS failover reroutes traffic within 300 seconds. Quarterly disaster recovery drills simulate full-datacenter blackouts.', 'Active' FROM departments WHERE department_code = 'DEP-ENG';
INSERT INTO policies (policy_code, title, category, version, effective_date, department_id, summary, full_text, status) SELECT 'POL-07', 'Remote Device Security & Endpoint Governance Policy', 'Internal Security', 'v3.0', '2023-11-15', id, 'Mandates full-disk encryption (FileVault/BitLocker), MDM enrollment, and zero local customer data caching on staff laptops.', 'All employee workstations must be corporate-managed, enrolled in Jamf/InTune MDM, and protected with active endpoint detection and response (EDR). Personnel are strictly prohibited from copying customer data or credentials to local drives or unapproved personal storage.', 'Active' FROM departments WHERE department_code = 'DEP-SEC';
INSERT INTO policies (policy_code, title, category, version, effective_date, department_id, summary, full_text, status) SELECT 'POL-08', 'Customer Data Retention & Secure Sanitization Policy', 'Data Governance', 'v2.1', '2024-04-01', id, 'Specifies cryptographic erasure and NIST 800-88 sanitization upon contract termination within 30 days.', 'Upon account cancellation or contract expiration, customer vector embeddings, uploaded files, and tenant caches are permanently erased within 30 days using NIST 800-88 compliant cryptographic wiping. A formal Certificate of Data Destruction is delivered to the customer compliance team.', 'Active' FROM departments WHERE department_code = 'DEP-SEC';
INSERT INTO policies (policy_code, title, category, version, effective_date, department_id, summary, full_text, status) SELECT 'POL-09', 'Intellectual Property & Custom Model Weights Ownership', 'Legal & IP', 'v1.5', '2023-08-01', id, 'Establishes that all fine-tuned weights, embeddings, and synthesized artifacts remain 100% customer property.', 'Customers retain sole and exclusive intellectual property ownership of all uploaded datasets, prompt histories, synthesized answers, and proprietary fine-tuned model adapter weights created using NexaData professional services. NexaData retains ownership of core platform algorithms and runtime SDKs.', 'Active' FROM departments WHERE department_code = 'DEP-FIN';
INSERT INTO policies (policy_code, title, category, version, effective_date, department_id, summary, full_text, status) SELECT 'POL-10', 'Enterprise Support Escalation & Incident Management', 'Support', 'v2.4', '2024-07-01', id, 'Outlines response times: Severity 1 (15 mins), Severity 2 (1 hour), Severity 3 (4 hours), and Severity 4 (24 hours).', 'Incident priorities are categorized from Sev-1 (critical outage or security breach) to Sev-4 (minor feature inquiry). Sev-1 issues immediately page the on-call SRE lead, engineering VP, and dedicated account executive. Post-mortem root cause analysis (RCA) reports are published within 5 business days.', 'Active' FROM departments WHERE department_code = 'DEP-CS';
INSERT INTO faqs (faq_code, category, question, answer, keywords, is_published, view_count) VALUES ('FAQ-01', 'Product Overview', 'What is NexaData AI and what solutions does it provide?', 'NexaData AI is an autonomous enterprise data intelligence platform. It provides document-grounded cognitive analysis, natural language SQL querying, secure client-isolated RAG, and executive analytics pipelines.', 'what is nexadata, solutions, overview, core capabilities, platform', TRUE, 196);
INSERT INTO faqs (faq_code, category, question, answer, keywords, is_published, view_count) VALUES ('FAQ-02', 'Pricing & Licensing', 'What are the pricing plans for NexaData AI?', 'Pricing starts at $1,500/month for the Developer API Gateway, $2,200/month for the Secure Sandbox, $4,800/month for Cloud Analytics, and $12,500/month for the Platinum Enterprise Engine. Custom appliances are available starting at $18,500.', 'pricing, cost, plans, tiers, license, subscription fee', TRUE, 743);
INSERT INTO faqs (faq_code, category, question, answer, keywords, is_published, view_count) VALUES ('FAQ-03', 'Data Privacy', 'Does NexaData AI use our company data to train general models?', 'No. Under our Zero Data Leakage Policy, customer data is never used for model training. Every enterprise deployment operates in a cryptographically isolated tenant enclave.', 'privacy, train models, data leakage, security, confidentiality', TRUE, 1128);
INSERT INTO faqs (faq_code, category, question, answer, keywords, is_published, view_count) VALUES ('FAQ-04', 'Database Integrations', 'Which databases and cloud warehouses does NexaData connect with?', 'NexaData natively connects to PostgreSQL, Snowflake, Oracle Exadata, Databricks, Apache Kafka, Microsoft SQL Server, BigQuery, and MongoDB Atlas.', 'databases, postgres, snowflake, oracle, kafka, integrations, connectors', TRUE, 357);
INSERT INTO faqs (faq_code, category, question, answer, keywords, is_published, view_count) VALUES ('FAQ-05', 'SLA & Support', 'What uptime SLA does NexaData offer?', 'We provide a 99.99% monthly uptime SLA for Platinum enterprise tiers and 99.9% for Cloud Analytics tiers, backed by 24/7 dedicated solutions engineering.', 'sla, uptime, availability, reliability, support', TRUE, 319);
INSERT INTO faqs (faq_code, category, question, answer, keywords, is_published, view_count) VALUES ('FAQ-06', 'Refunds & Guarantees', 'Is there a money-back satisfaction guarantee?', 'Yes. All subscription tiers carry an unconditional 14-day 100% money-back satisfaction guarantee upon initial deployment.', 'refund, money back guarantee, satisfaction guarantee, cancel', TRUE, 600);
INSERT INTO faqs (faq_code, category, question, answer, keywords, is_published, view_count) VALUES ('FAQ-07', 'Compliance', 'Is NexaData AI SOC2 and HIPAA compliant?', 'Yes. NexaData is certified SOC2 Type II compliant and offers BAA agreements for HIPAA-regulated healthcare organizations via our dedicated security enclaves.', 'soc2, hipaa, compliance, regulations, certification, baa', TRUE, 1220);
INSERT INTO faqs (faq_code, category, question, answer, keywords, is_published, view_count) VALUES ('FAQ-08', 'Deployment Options', 'Can NexaData AI be deployed on-premises or air-gapped?', 'Yes. We offer the NexaData Edge AI Appliance Server (ND-EDG-09) and containerized air-gapped Kubernetes packages for defense, healthcare, and financial institutions.', 'on-premises, air-gapped, edge appliance, hardware, private cloud', TRUE, 397);
INSERT INTO faqs (faq_code, category, question, answer, keywords, is_published, view_count) VALUES ('FAQ-09', 'Sales & Billing', 'What payment methods are supported for enterprise orders?', 'We support Wire Transfer, ACH Corporate transfers, Credit Cards, and Purchase Orders on Net 30/60 terms.', 'payment methods, wire transfer, ach, credit card, purchase order, invoice', TRUE, 915);
INSERT INTO faqs (faq_code, category, question, answer, keywords, is_published, view_count) VALUES ('FAQ-10', 'Document Formats', 'What file types can be uploaded and analyzed by NexaData AI?', 'The platform accepts PDF, Word (DOCX), Plain Text (TXT), CSV datasets, and image formats (PNG, JPG, JPEG, WEBP) up to 10 MB per file.', 'file types, upload, pdf, docx, csv, images, txt, format support', TRUE, 1049);
INSERT INTO faqs (faq_code, category, question, answer, keywords, is_published, view_count) VALUES ('FAQ-11', 'AI Models', 'What AI models power NexaData conversational responses?', 'NexaData leverages state-of-the-art vision and language models (including OpenAI GPT-4o and specialized open-source embeddings), grounded in verified relational schemas and indexed documents.', 'models, llm, gpt-4o, openai, embeddings, vector search', TRUE, 879);
INSERT INTO faqs (faq_code, category, question, answer, keywords, is_published, view_count) VALUES ('FAQ-12', 'Company Background', 'Where is NexaData headquartered and when was it founded?', 'NexaData AI Solutions was founded in 2021 and is headquartered at 100 Technology Square, Suite 500, Cambridge, MA 02139, USA.', 'headquarters, founded, location, cambridge, address, company background', TRUE, 1493);
INSERT INTO faqs (faq_code, category, question, answer, keywords, is_published, view_count) VALUES ('FAQ-13', 'Voice Input', 'Does NexaData AI support voice dictation and multilingual queries?', 'Yes. The chat input features microphone voice dictation with real-time speech recognition supporting English and Hindi.', 'microphone, voice, speech recognition, hindi, dictation, audio', TRUE, 1226);
INSERT INTO faqs (faq_code, category, question, answer, keywords, is_published, view_count) VALUES ('FAQ-14', 'Customer Success', 'How quickly can NexaData be deployed in an existing enterprise stack?', 'Cloud Analytics and API tiers can be provisioned in under 15 minutes. Custom enterprise legacy migrations typically complete within 5 to 10 business days.', 'onboarding, deployment time, setup, implementation, timeline', TRUE, 978);
INSERT INTO faqs (faq_code, category, question, answer, keywords, is_published, view_count) VALUES ('FAQ-15', 'Contact & Support', 'How can I contact NexaData enterprise support?', 'Enterprise support is available 24/7 via support@nexadata.ai, by phone at +1 (800) 555-6392, or directly through the assistant chat.', 'contact, email, phone, support desk, help, reach support', TRUE, 1322);
